#!/usr/bin/env python3
"""Writes the secret code's alphabet and the texts the tests of Specs/peer_rules.t27 use, from the readable lists below.

The spec carries one generated block, between
    ; >>> generated by Specs/tables/peer_tables.py -- edit the lists there, not here
    ; <<< generated
with the alphabet, named row indexes and the texts as packed UTF-8 bytes with offsets and lengths (t27 has no
string arrays that reach C). Run by Specs/generate.sh; edit the lists here, not the spec. The table layout is
ponte_tables.table, so every spec's fixtures read the same way.
"""
import pathlib
import re
import sys

sys.dont_write_bytecode = True
from ponte_tables import arr, table  # noqa: E402  (same folder; generate.sh runs this file directly)

SPECS = pathlib.Path(__file__).resolve().parents[1]
BEGIN = "; >>> generated by Specs/tables/peer_tables.py -- edit the lists there, not here"

# The secret code shared only among the Russians (secretAlphabet): digits and lowercase ASCII letters without
# 0 1 i l o, which are misread for one another when a code is read out or typed.
SECRET_ALPHABET = "23456789abcdefghjkmnpqrstuvwxyz"

# What this Ponte's recognizer heard (the phrase) and what a Ponte said into the call (its TTS): containment and word
# counts; the review's cases of short Brazilian replies; secret codes as typed or pasted, with what they normalize to
# and how they are shown.
FIXTURES = [
    ("TTS_CONTRACT", "Entao fica combinado assim: eu preparo tudo hoje a noite e voces podem revisar com calma e, "
                     "se quiserem, assinar o contrato amanha de manha."),
    ("HEARD_TAIL", "o contrato amanha de manha"),
    ("TTS_CONTRACT_PT", "Então fica combinado assim: eu preparo tudo hoje à noite e vocês podem revisar "
                        "com calma e, se quiserem, assinar o contrato amanhã de manhã."),
    ("HEARD_TAIL_PT", "o contrato amanhã de manhã"),
    ("REPLY", "Sim, podemos comecar agora"),
    ("TTS_QUESTION", "Podemos comecar agora?"),
    ("PHRASE_SEND", "Podemos enviar o contrato amanha"),
    ("TTS_SEND", "Voces podem enviar o contrato hoje?"),
    ("ORDER_SWAPPED", "contrato o"),
    ("ORDER", "o contrato"),
    ("SIM_THREE", "sim sim sim"),
    ("SIM_ONE", "Sim."),
    ("NO_WORDS", "... -- ?!"),
    ("EMPTY", ""),
    # The review (2026-10-14): the owner's TTS named a price, the Brazilian asked it back in two words.
    ("TTS_PRICE", "O preco e dez mil reais"),
    ("REPLY_PRICE", "Dez mil?"),
    ("REPLY_SURE", "Sim, claro"),
    # Words: Cyrillic letters are word bytes but their capitals are not folded (ASCII only); digits are word bytes;
    # a hyphen and an apostrophe split words; an accented letter is part of its word.
    ("RU_PRIVET", "Привет, как дела?"),
    ("RU_PRIVET_LOWER", "привет как дела"),
    ("DIGITS", "Sala 2026, andar 10"),
    ("HYPHENS", "quinta-feira, d'agua"),
    ("ACCENTS", "Ação já!"),
    ("SECRET_TYPED", "ABCD efgh-JKMN"),
    ("SECRET", "abcdefghjkmn"),
    ("SECRET_DISPLAY", "abcd-efgh-jkmn"),
    ("SECRET_ZERO", "abcd-efgh-jkm0"),
    ("SECRET_UNDERSCORES", "  2345_6789_WXYZ  "),
    ("SECRET_UNDERSCORES_NORMALIZED", "23456789wxyz"),
    ("SECRET_UNDERSCORES_DISPLAY", "2345-6789-wxyz"),
    ("SECRET_SHORT", "abcd-efgh-jkm"),
    ("SECRET_LONG", "abcd-efgh-jkmnp"),
    ("SECRET_WITH_I", "abcd-efgh-ijkm"),
    ("SECRET_TABS", "abcd\tefgh\tjkmn"),
    ("SECRET_ACCENT", "abcd-éfgh-jkmn"),
    ("SECRET_UPPER", "ABCDEFGHJKMN"),
]


def write_block(spec_name, lines, begin=BEGIN):
    spec = SPECS / spec_name
    source = spec.read_text()
    block = "\n".join([begin] + lines + ["; <<< generated"])
    source, n = re.subn(re.escape(begin) + r".*?; <<< generated", lambda _: block, source, flags=re.S)
    if n != 1:
        sys.exit(f"{spec_name}: generated block not found")
    if any(ord(ch) > 127 for ch in source):
        sys.exit(f"{spec_name}: not ASCII after generation")
    if spec.read_text() != source:
        spec.write_text(source)


def secret_alphabet_lines():
    alphabet = SECRET_ALPHABET
    assert len(alphabet) == 31 and len(set(alphabet)) == len(alphabet), "31 distinct bytes"
    assert list(alphabet) == sorted(alphabet), "sorted, so a reader sees at once what is missing"
    assert all(c in "0123456789abcdefghijklmnopqrstuvwxyz" for c in alphabet), "digits and lowercase ASCII letters"
    assert not set("01ilo") & set(alphabet), "no 0 1 i l o"
    return [f"; The secret code's alphabet: {alphabet}",
            f"pub const PE_SECRET_ALPHABET_LEN : i64 = {len(alphabet)};",
            arr("PE_SECRET_ALPHABET", "u8", list(alphabet.encode("ascii")))]


def main():
    names = [name for name, _ in FIXTURES]
    assert len(set(names)) == len(names), "fixture names are unique"
    lines = secret_alphabet_lines() + table("PE_FX", "Texts for the tests", FIXTURES, [])
    write_block("peer_rules.t27", lines)
    print(f"peer tables: {len(FIXTURES)} fixtures, a secret alphabet of {len(SECRET_ALPHABET)}")


if __name__ == "__main__":
    main()
